<?php require __DIR__.'/../app/bootstrap.php';require_login();$u=current_user($pdo);$service=$_GET['service']??'electricity';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$service=$_POST['service']??'';$customer=preg_replace('/\D+/','',$_POST['customer']??'');$provider=$_POST['provider']??'';$variation=$_POST['variation']??'';$amount=(float)($_POST['amount']??0);if(!in_array($service,['electricity','tv'],true)||!$customer||!$provider||!$variation||$amount<=0){flash('error','Complete all bill payment fields.');header('Location:/bills.php?service='.urlencode($service));exit;}try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT balance FROM wallets WHERE user_id=? FOR UPDATE');$q->execute([$u['id']]);$bal=(float)$q->fetchColumn();$charge=round($amount*1.01,2);if($bal<$charge)throw new RuntimeException('Insufficient wallet balance.');$ref='BIL-'.date('YmdHis').'-'.bin2hex(random_bytes(4));$pdo->prepare('UPDATE wallets SET balance=balance-? WHERE user_id=?')->execute([$charge,$u['id']]);$pdo->prepare('INSERT INTO wallet_transactions(user_id,type,amount,reference,description) VALUES(?,?,?,?,?)')->execute([$u['id'],'debit',$charge,$ref,ucfirst($service).' payment']);$wt=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO service_transactions(user_id,service,customer,network,package_name,amount,cost_amount,reference) VALUES(?,?,?,?,?,?,?,?)')->execute([$u['id'],$service,$customer,$provider,$variation,$charge,$amount,$ref]);$sid=(int)$pdo->lastInsertId();$pdo->commit();try{$v=new VtuProvider($config['vtu']);if($service==='electricity')$r=$v->electricity($provider,$customer,$variation,$amount,$ref);else $r=$v->tv($provider,$customer,$variation,$amount,$ref);if(!provider_ok($r))throw new RuntimeException($r['message']??'Bill payment failed.');$pdo->prepare('UPDATE service_transactions SET status="successful",provider_reference=? WHERE id=?')->execute([provider_ref($r),$sid]);notify($pdo,$u['id'],ucfirst($service).' payment successful','Your '.ucfirst($service).' payment was processed successfully.');flash('success',ucfirst($service).' payment successful.');}catch(Throwable $ex){$pdo->beginTransaction();$pdo->prepare('UPDATE service_transactions SET status="reversed" WHERE id=?')->execute([$sid]);$pdo->prepare('UPDATE wallet_transactions SET status="reversed" WHERE id=?')->execute([$wt]);$pdo->prepare('UPDATE wallets SET balance=balance+? WHERE user_id=?')->execute([$charge,$u['id']]);$pdo->commit();flash('error','Bill payment failed; your wallet was reversed.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}header('Location:/bills.php?service='.urlencode($service));exit;}require __DIR__.'/../app/layout.php';header_html('Bills');?><div class="card narrow"><div class="tabs"><a class="<?= $service==='electricity'?'active':''?>" href="?service=electricity">Electricity</a><a class="<?= $service==='tv'?'active':''?>" href="?service=tv">Cable TV</a></div><h2><?=ucfirst($service)?></h2><p class="muted">1% service markup is included in the wallet charge.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="service" value="<?=e($service)?>"><div class="field"><label><?= $service==='electricity'?'Provider':'Provider'?></label><select name="provider" required><?php if($service==='electricity'):?><option value="abuja-electric">Abuja Electricity (AEDC)</option><option value="jos-electric">Jos Electricity (JED)</option><option value="kano-electric">Kano Electricity (KEDCO)</option><option value="ikeja-electric">Ikeja Electricity</option><option value="eko-electric">Eko Electricity</option><?php else:?><option value="dstv">DStv</option><option value="gotv">GOtv</option><option value="startimes">Startimes</option><option value="showmax">Showmax</option><?php endif;?></select></div><div class="field"><label><?= $service==='electricity'?'Meter number':'Smartcard / IUC number'?></label><input name="customer" inputmode="numeric" required></div><div class="field"><label><?= $service==='electricity'?'Meter type':'Package / variation ID'?></label><input name="variation" placeholder="<?= $service==='electricity'?'prepaid or postpaid':'Enter provider variation ID'?>" required></div><div class="field"><label>Amount</label><input type="number" name="amount" min="100" step="1" required></div><button class="btn">Pay <?=ucfirst($service)?></button></form></div><?php footer_html();
